def option(args,name):
 values=[]
 for index,arg in enumerate(args):
  if arg==name and index+1<len(args):values.append(args[index+1])
  elif arg.startswith(name+'='):values.append(arg[len(name)+1:])
 if len(values)!=1:raise ValueError((name,values))
 return values[0]


def describe(arguments,environment,role):
 opts=compiler_options(arguments)
 opts['explicit_edition']=opts['edition']
 opts['edition']=opts['edition'] or '2015'
 package=environment.get('CARGO_PKG_NAME')
 version=environment.get('CARGO_PKG_VERSION')
 if not package or not version:raise ValueError(('missing package identity',environment,arguments))
 declared_types=[]
 for index,arg in enumerate(arguments):
  if arg=='--crate-type':declared_types.extend(arguments[index+1].split(','))
  elif arg.startswith('--crate-type='):declared_types.extend(arg[len('--crate-type='):].split(','))
 opts['declared_crate_types']=declared_types
 if set(declared_types)&{'lib','rlib'}:
  kind='rlib'
 elif len(declared_types)==1:
  kind=declared_types[0]
 else:
  raise ValueError(('unmodeled crate types',declared_types))
 features=tuple(sorted(cfg for cfg in opts['cfg'] if cfg.startswith('feature=')))
 key=(package,version,option(arguments,'--crate-name'),kind,role,features)
 return key,opts


